function restoreWorkflowFocus(controlId,stepId,focusGuard){if(document.activeElement!==focusGuard&&document.activeElement!==document.body)return;const preferred=controlId&&document.getElementById(controlId),target=preferred&&!preferred.disabled?preferred:document.getElementById('paletteStep-'+stepId);target?.focus({preventScroll:true})}
