function handleWorkflowStepKey(event){const tabs=[...event.currentTarget.querySelectorAll('[role="tab"]')].filter(tab=>!tab.hidden&&!tab.disabled);if(!tabs.length)return;const current=Math.max(0,tabs.indexOf(document.activeElement));let next=null;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(current+1)%tabs.length;else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(current-1+tabs.length)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;if(next===null)return;event.preventDefault();const intendedStep=tabs[next].dataset.step;tabs[next].click();if(document.activeElement===tabs[next])document.getElementById('paletteStep-'+intendedStep)?.focus()}
function showWorkflow(){const mode=workflowModes[activeMode]||workflowModes.modify,keys=Object.keys(mode.steps),step=mode.steps[activeStep]?activeStep:keys[0],stepIndex=keys.indexOf(step),current=mode.steps[step],hasNext=stepIndex+1<keys.length;activeStep=step;for(const item of sectionNodes.values())document.querySelector('.section-store').append(item);const panel=document.querySelector('.workflow-panel');panel.id='paletteWorkflowPanel';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','paletteStep-'+step);panel.textContent='';const guide=document.createElement('section');guide.className='step-guide';guide.innerHTML='<div><h2>'+esc(current.label.replace(/^\d+\s*/,''))+'</h2><p>'+esc(current.guide)+'</p></div><div class="step-guide-actions"><button id="flowBack" '+(stepIndex?'':'disabled title="Already at the first step."')+'>Back</button><button id="flowNext" '+(hasNext?'':'disabled title="This is the final step. Use its explicit review, save, build, or adopt action to finish."')+'>'+(hasNext?'Next':'Final step')+'</button></div>';panel.append(guide);guide.querySelector('#flowBack').onclick=()=>{if(stepIndex)activateWorkflowStep(keys[stepIndex-1],document.activeElement,'flowBack')};guide.querySelector('#flowNext').onclick=()=>{if(hasNext)activateWorkflowStep(keys[stepIndex+1],document.activeElement,'flowNext')};const paths=quickPaths(activeMode,step);if(paths.length){const launchers=document.createElement('div');launchers.className='quick-paths';launchers.setAttribute('aria-label','Common tasks');for(const item of paths){const button=document.createElement('button');button.className='quick-path';button.innerHTML='<b>'+esc(item.label)+'</b><small>'+esc(item.hint)+'</small>';button.onclick=()=>{const[kind,value]=item.action.split(':');if(kind==='post')post(value);else if(kind==='step')activateWorkflowStep(value,document.activeElement)};launchers.append(button)}panel.append(launchers)}const preferredSection=current.sections.includes(session.context.section)?session.context.section:current.sections[0];for(const id of current.sections){const item=sectionNodes.get(id);if(item){item.open=sectionDisclosureState.has(id)?sectionDisclosureState.get(id):id===preferredSection;panel.append(item)}}for(const button of sections.querySelectorAll('.flow-choice')){const selected=button.dataset.mode===activeMode;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected))}const stepTabs=document.querySelector('.step-tabs');stepTabs.setAttribute('role','tablist');stepTabs.onkeydown=handleWorkflowStepKey;stepTabs.textContent='';for(const [id,item]of Object.entries(mode.steps)){const selected=id===step,button=document.createElement('button');button.id='paletteStep-'+id;button.className='step-tab'+(selected?' active':'');button.textContent=item.label;button.dataset.step=id;button.setAttribute('role','tab');button.setAttribute('aria-selected',String(selected));button.setAttribute('aria-controls','paletteWorkflowPanel');button.tabIndex=selected?0:-1;button.onclick=()=>activateWorkflowStep(id,document.activeElement,'paletteStep-'+id);stepTabs.append(button)}document.querySelector('.workflow-intro').textContent=mode.intro;if(activeMode==='template'&&activeStep==='image')requestTemplateLayout()}
function arrangeWorkspace(){if(sectionNodes.size&&sections.querySelector(':scope > .palette-desk'))return;const all=[...sections.querySelectorAll(':scope > details')],byId=id=>all.find(item=>item.dataset.section===id),desk=document.createElement('section'),choices=document.createElement('nav'),stepTabs=document.createElement('nav'),intro=document.createElement('p'),panel=document.createElement('section'),store=document.createElement('section');sectionNodes=new Map(all.map(item=>[item.dataset.section,item]));desk.className='palette-desk';desk.setAttribute('aria-label','Persistent palette work area');for(const id of ['live-edit','embedded']){const item=byId(id);if(item){sectionNodes.delete(id);item.open=sectionDisclosureState.has(id)?sectionDisclosureState.get(id):true;desk.append(item)}}choices.className='flow-choices';choices.setAttribute('aria-label','Choose a palette workflow');for(const[id,mode]of Object.entries(workflowModes)){const button=document.createElement('button');button.className='flow-choice';button.dataset.mode=id;button.innerHTML='<b>'+esc(mode.label)+'</b><br><span>'+esc(mode.intro)+'</span>';button.onclick=()=>{activeMode=id;activeStep='';showWorkflow()};choices.append(button)}stepTabs.className='step-tabs';stepTabs.setAttribute('aria-label','Steps in selected palette workflow');intro.className='workflow-intro';panel.className='workflow-panel';store.className='section-store';for(const item of sectionNodes.values())store.append(item);sections.textContent='';sections.append(desk,choices,intro,stepTabs,panel,store);if(!workflowModes[activeMode]){const requested=session.context.section,originSurface=String(session.context.origin?.surface||'');activeMode=originSurface.includes('image-clean')?'clean':requested==='template'?'template':requested==='index-migration'?'modify':session.context.kind==='existing-sff'?'modify':String(session.context.origin?.kind||'').includes('template')?'template':'create';for(const[stepId,step]of Object.entries(workflowModes[activeMode].steps))if(step.sections.includes(requested))activeStep=stepId}showWorkflow()}
