function handleTopologyKey(event){const options=[...event.currentTarget.querySelectorAll('[role="option"]:not(:disabled)')];if(!options.length)return;const current=Math.max(0,options.indexOf(document.activeElement));let next=null;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=Math.min(options.length-1,current+1);else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=Math.max(0,current-1);else if(event.key==='Home')next=0;else if(event.key==='End')next=options.length-1;if(next===null)return;event.preventDefault();options[next].focus()}
function renderTopologyLayout(){const host=sections.querySelector('[data-body="topology-layout"]');if(!host)return;if(session.context.kind!=='existing-sff'){host.innerHTML='<p class="muted">Choose an exact SFF target or indexed image before arranging palette indexes.</p>';return}const snapshot=migration?.snapshot;if(!snapshot){host.innerHTML='<p>Start from the current master palette or an indexed PNG family. Work stays in a retained draft; the active SFF and source images remain unchanged.</p><div class="topology-toolbar"><button id="layoutStartSff">Use current SFF palette</button><button id="layoutStartPng">Use indexed PNG family…</button></div>'+(migration?.error?'<p class="blocked" role="alert">'+esc(migration.error)+'</p>':'');host.querySelector('#layoutStartSff').onclick=()=>post('migrationStartSff');host.querySelector('#layoutStartPng').onclick=()=>post('migrationStartPng');return}const plan=snapshot.plan,selected=new Set(session.migration?.selectedSourceIndexes||[]),authority=snapshot.authority,output=authority.kind==='standalone-indexed-png-family'?'migrationCopies':'migrationHandoff';host.innerHTML='<p class="family-status"><b>Master index layout</b> · revision '+snapshot.revision+' · '+selected.size+' selected · index 0 locked</p><div class="topology-toolbar" role="toolbar" aria-label="Move selected palette indexes"><button data-move="left" title="Move left" aria-label="Move selected indexes left">←</button><button data-move="right" title="Move right" aria-label="Move selected indexes right">→</button><button data-move="up" title="Move up" aria-label="Move selected indexes up">↑</button><button data-move="down" title="Move down" aria-label="Move selected indexes down">↓</button><input id="layoutGroupName" placeholder="Named swatch group" aria-label="Named swatch group"><button id="layoutGroup">Name selection</button></div><div class="topology-grid" id="layoutGrid" role="listbox" aria-multiselectable="true" aria-label="Exact 256-slot master palette layout"></div><fieldset><legend>Add or reserve an index</legend><label>Slot <input id="layoutAt" type="number" min="1" max="255" value="1"></label><label>RGBA <input id="layoutRgba" value="0,0,0,255"></label><label>Name <input id="layoutColorName" value="New color"></label><button id="layoutAddColor">Add color</button><button id="layoutAddGap">Reserve slot</button></fieldset><div class="topology-toolbar"><button id="layoutCheckpoint">Save reviewed layout</button><button id="layoutOutput">'+(output==='migrationCopies'?'Create reviewed copies…':'Export SFF build handoff…')+'</button></div><details><summary>Exact mapping and audit</summary><p>'+snapshot.mapping.oldToNew.map((value,index)=>index+'→'+value).join(' · ')+'</p><p>'+((snapshot.duplicates||[]).map(item=>esc(item.message)).join(' · ')||'No duplicate-color ambiguity found.')+'</p></details>';const grid=host.querySelector('#layoutGrid');grid.onkeydown=handleTopologyKey;plan.slots.forEach((slot,destination)=>{const button=document.createElement('button');const source=slot?.kind==='source'?slot.sourceIndex:null,chosen=source!==null&&selected.has(source);button.className=chosen?'selected':'';button.disabled=!slot||slot.kind!=='source'||source===0;button.setAttribute('role','option');button.style.background=slot?'rgba('+slot.rgba.slice(0,3).concat(slot.rgba[3]/255).join(',')+')':'transparent';button.title='Destination '+destination+(source!==null?' from source '+source:' · '+(slot?.kind||'empty'));button.setAttribute('aria-label',button.title+(source===0?' · locked transparent index':''));button.setAttribute('aria-selected',String(chosen));button.onclick=()=>{const next=new Set(selected);next[next.has(source)?'delete':'add'](source);post('migrationSelect',{sourceIndexes:[...next]})};grid.append(button)});host.querySelectorAll('[data-move]').forEach(button=>button.onclick=()=>post('migrationMove',{direction:button.dataset.move}));host.querySelector('#layoutGroup').onclick=()=>{const name=host.querySelector('#layoutGroupName').value.trim();if(name)post('migrationGroup',{name})};host.querySelector('#layoutAddColor').onclick=()=>post('migrationInsertColor',{at:Number(host.querySelector('#layoutAt').value),rgba:host.querySelector('#layoutRgba').value.split(',').map(Number),label:host.querySelector('#layoutColorName').value});host.querySelector('#layoutAddGap').onclick=()=>post('migrationInsertGap',{at:Number(host.querySelector('#layoutAt').value),count:1,label:'Reserved slot'});host.querySelector('#layoutCheckpoint').onclick=()=>post('migrationCheckpoint');host.querySelector('#layoutOutput').onclick=()=>post(output)}
